<?php
namespace App\Jobs;
use App\Models\CouponDistributionTask;use App\Models\CouponTemplate;use App\Services\CouponAudienceService;use App\Services\CouponWalletService;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;
class ProcessCouponDistributionTask implements ShouldQueue { use Dispatchable,InteractsWithQueue,Queueable,SerializesModels; public $taskId; public function __construct(int $taskId){$this->taskId=$taskId;} public function handle(CouponWalletService $service,CouponAudienceService $audience){$task=CouponDistributionTask::find($this->taskId);if(!$task||$task->status==='cancelled')return;$task->status='running';$task->save();$q=$audience->query($task->filters);$template=CouponTemplate::find($task->template_id);if(!$template)throw new \RuntimeException('优惠券模板不存在');$q->orderBy('id')->chunkById(200,function($users)use($service,$template,$task){$task->refresh();if($task->status==='cancelled')return false;foreach($users as $user){try{$coupon=$service->issue($template,$user,'distribution_task',(string)$task->id);$coupon?$task->success_count++:$task->skipped_count++;}catch(\Throwable $e){report($e);$task->failed_count++;}$task->save();}});$task->refresh();if($task->status==='cancelled')return;$task->status=$task->failed_count?'partial':'completed';$task->completed_at=time();$task->save();} public function failed(\Throwable $e){$task=CouponDistributionTask::find($this->taskId);if(!$task||$task->status==='cancelled')return;$task->status='partial';$task->failed_count=max(1,(int)$task->failed_count);$task->completed_at=time();$task->save();} }
